use vstd::prelude::*;

verus! {
    /// Given two i8’s `n` and `m`, returns
    ///   - `first  = max(n,m) - 1`
    ///   - `second = min(n,m)`
    ///
    /// We require `max(n,m) > i8::MIN` so that the subtraction cannot underflow.
    fn solve(n: i8, m: i8) -> (first: i8, second: i8)
        requires
            n.max(m) > i8::MIN,
        ensures
            first  == n.max(m) - 1,
            second == n.min(m),
    {
        // second is the smaller of the two inputs
        let second = n.min(m);
        // first is the larger input minus 1
        let first = n.max(m) - 1;
        (first, second)
    }
}

